const REVIEW={legal:'Gangarten aller Figuren kurz zeigen lassen.',passed:'Bauernzug, Doppelschritt, Bauernschlag und Umwandlung zeigen lassen.',queenmate:'Eine Matt- und eine Pattstellung vergleichen.',tworooks:"Ein Damenmatt am Rand zeigen lassen: Wer sperrt, wer gibt Schach?",counter:"Angegriffen oder in Gefahr? An zwei Stellungen zeigen lassen, wer angreift und wer deckt.",skewer:"Eine Spießstellung und eine Fesselungsstellung vergleichen: Wo steht die wertvollere Figur?",clock:'Drei Züge in Notation vorlesen, die Kinder spielen sie nach.',coordinates:'Brett richtig hinlegen: rechts unten ein helles Feld. Jedes Kind zeigt es.',moves:'Feldnamen: Du nennst drei Felder, die Kinder zeigen sie.',pawn:'Gangarten von Turm, Läufer und Springer am Demobrett zeigen lassen.',defend:'Drei Schlagzüge am Demobrett zeigen lassen: Welche Figur kann was schlagen?',check:'Angegriffen oder gedeckt? An einer Stellung zeigen lassen, wer zurückschlägt.',mateIn1:'Die drei Schach-Abwehren an die Tafel: wegziehen, dazwischenstellen, schlagen.',fairplay:'Zwei Grundregeln wiederholen: Berührt, geführt. Schach muss abgewehrt werden.',hangingPiece:'Figurenwerte an die Tafel: Bauer 1, Springer 3, Läufer 3, Turm 5, Dame 9.',fork:'Eine Stellung zeigen: Welche Figur ist ungedeckt? Wer schlägt zurück?',pin:'Linienfiguren: Turm, Läufer und Dame zeigen lassen, wen sie angreifen.',opening:'Grundstellung: Welche Figuren müssen zuerst ins Spiel? Kinder zeigen sie.',endgame:'Königszüge und Bauernumwandlung kurz am Demobrett zeigen.',discoveredAttack:'Eine Linienfigur zeigen, die von einer eigenen Figur blockiert wird.',mateIn2:'Ein Matt in einem Zug gemeinsam lösen und die drei Abwehren prüfen.',calculation:'Gabel, Fesselung und Abzug je an einem Beispiel benennen lassen.',planning:'Stellungsmerkmale sammeln: offene Linien, schwache Bauern, Königssicherheit.',rookend:'Turmzüge und das Grundreihenmatt kurz am Demobrett zeigen.',castling:'Königs- und Turmzüge zeigen, dann: Wann steht der König im Schach?',promotion:'Bauernzug, Doppelschritt und Bauernschlag kurz zeigen lassen.',stalemate:'Schach und Matt: Was ist der Unterschied? Ein Beispiel zeigen.',notation:'Feldnamen: Du nennst drei Felder, die Kinder zeigen sie.',enpassant:'Bauernzug, Bauernschlag und Doppelschritt vom Startfeld zeigen lassen.',doublecheck:'Die drei Schach-Abwehren und den Abzugsangriff kurz wiederholen.',exchange:'Figurenwerte an die Tafel: Bauer 1, Springer 3, Läufer 3, Turm 5, Dame 9.'};
const FIT={under:'Gruppe noch unter dem Themenniveau: Wiederholung zu Beginn, informativer Einstieg, weniger Pflichtaufgaben, Hilfen von Anfang an.',over:'Gruppe über dem Themenniveau: kürzere Erarbeitung, mehr Übungszeit, Expertenaufgabe für alle, Profi-Aufgabe für Schnelle.',mixed:'Unterschiedliches Vorwissen: gemischte Paare nach Regel, gestufte Pflichtaufgaben.'};
function adapt(plan){const P=window.PlanningExtensions;if(!P?.fit)return plan;for(const s of plan.sessions){const t=s.topic||plan.settings.topic;if(s.fit||s.stunde0||!s.merksatz)continue;const f=P.fit(plan.settings,t);s.fit=f;if(f==='fit')continue;s.fitNote=FIT[f];
const ph=k=>s.phases.find(x=>x.name.startsWith(k)),e=ph('Einstieg'),er=ph('Erarbeitung'),u=ph('Übung');const shift=(from,to,m)=>{if(from&&to&&from.duration-m>=3){from.duration-=m;to.duration+=m}};
if(f==='under'){if(e&&REVIEW[t]){{const w='Wiederholung (2 Min.): '+REVIEW[t]+' ',k='Partner kontrolliert. ',i=e.scan_teacher.indexOf(k);e.scan_teacher=i>=0?e.scan_teacher.slice(0,i+k.length)+w+e.scan_teacher.slice(i+k.length):w+e.scan_teacher}e.teacher='Wiederholung des nötigen Vorwissens (2 Minuten): '+REVIEW[t]+' '+e.teacher;shift(u,e,2)}
if(u){u.scan_teacher=String(u.scan_teacher).replace('Hilfekarten in die Mitte','Hilfekarte Stufe 1 gleich an jedes Paar');u.scan_learners=String(u.scan_learners).replace(/Pflicht: Aufgabe 3 und 4, dann 5; Expertenaufgabe 6\./,'Pflicht: Aufgabe 3 und 4 mit Hilfekarte. Aufgabe 5 und 6 freiwillig.');u.diff='Pflicht nur Aufgabe 3 und 4, Hilfekarte Stufe 1 liegt von Anfang an bereit. Aufgabe 5 und 6 freiwillig.'}}
if(f==='over'){shift(er,u,2);if(er)er.scan_teacher=String(er.scan_teacher)+' Kurz halten: Die Gruppe kennt die Grundlagen.';if(u){u.scan_learners=String(u.scan_learners).replace(/Pflicht: Aufgabe 3 und 4, dann 5; Expertenaufgabe 6\./,'Pflicht: Aufgabe 3 bis 6 mit Expertenaufgabe. Wer fertig ist: Profi-Aufgabe.');u.diff='Pflicht für alle: Aufgabe 3 bis 6. Schnelle lösen die Profi-Aufgabe (unten).'}}
if(f==='mixed'&&u){u.scan_teacher=String(u.scan_teacher).replace('Arbeitsblatt Teil B und C,','Paare nach Spielstärke mischen (Regel unten). Arbeitsblatt Teil B und C,');u.scan_learners=String(u.scan_learners).replace(/Pflicht: Aufgabe 3 und 4, dann 5; Expertenaufgabe 6\./,'Pflicht für alle: Aufgabe 3 und 4. Stärkere zusätzlich 5, 6 und die Profi-Aufgabe.');u.diff='Pflicht für alle: Aufgabe 3 und 4. Stärkere zusätzlich Aufgabe 5, 6 und die Profi-Aufgabe.'}
const pr=u;if(pr){const m=Math.max(4,Math.round(pr.duration*0.4));for(const k of ['teacher','scan_teacher'])pr[k]=String(pr[k]).replace(/(letzte|Letzte) \d+ Minuten/g,(x,w)=>w+' '+m+' Minuten')}}return plan}
// Einzelförderung: Texte für ein einzelnes Kind statt Partner- und Gruppenarbeit.
const SOLO=[[/Bretter aufbauen lassen, Partner kontrolliert\. /g,'Brett aufbauen lassen. '],[/Bretter in Startstellung („[^“]+“) aufbauen lassen\./g,'Brett in Startstellung $1 aufbauen lassen.'],[/Paare bilden, /g,''],[/Bretter in Grundstellung aufbauen, Partner kontrolliert/g,'Brett in Grundstellung aufbauen'],[/Bretter in die Startstellung von („[^“]+“) aufbauen, Partner kontrolliert/g,'Brett in die Startstellung von $1 aufbauen'],[/Jedes Kind entscheidet still, zwei Vermutungen mit Grund hören\./g,'Das Kind entscheidet still und nennt seine Vermutung mit Grund.'],[/Jedes Kind entscheidet still und zeigt seine Vermutung/g,'Das Kind entscheidet still und zeigt seine Vermutung'],[/Zwei verschiedene Vermutungen mit Grund nennen lassen, nicht bewerten\./g,'Die Vermutung mit Grund nennen lassen, nicht bewerten.'],[/Kinder entscheiden erst/g,'Das Kind entscheidet erst'],[/Kinder nennen jeden Schritt/g,'Das Kind nennt jeden Schritt'],[/die Kinder machen weiter/g,'das Kind macht weiter'],[/die Kinder führen die übrigen Schritte aus/g,'das Kind führt die übrigen Schritte aus'],[/Rückfrage: Wer sagt die Regel in eigenen Worten\?/g,'Rückfrage: Das Kind sagt die Regel in eigenen Worten.'],[/Gruppe gegen Lehrkraft/g,'Kind gegen Lehrkraft'],[/Die Kinder schlagen per Handzeichen Züge vor/g,'Das Kind schlägt Züge vor'],[/die Kinder schlagen per Handzeichen Züge vor und begründen sie/g,'das Kind schlägt Züge vor und begründet sie'],[/Was fällt euch (dazu )?ein\?/g,'Was fällt dir dazu ein?'],[/Hilfekarten in die Mitte\. Herumgehen, bei Fehlern/g,'Hilfekarten bereitlegen. Daneben sitzen, bei Fehlern'],[/Hilfekarte Stufe 1 gleich an jedes Paar/g,'Hilfekarte Stufe 1 gleich bereitlegen'],[/Häufigsten Fehler für die Sicherung notieren\./g,'Fehler für die Sicherung notieren.'],[/Häufigsten Fehler aus der Übung ohne Namen zeigen/g,'Den Fehler aus der Übung noch einmal ansehen'],[/Paare nach Spielstärke mischen \(Regel unten\)\. /g,''],[/Zu zweit: A löst, B prüft mit dem Denkweg, dann wechseln\. /g,'Lösen, dann mit dem Denkweg selbst prüfen. '],[/ Zwei Paare gezielt beobachten\./g,''],[/; ein Brett pro Paar/g,'; ein Brett'],[/ein Brett pro Paar/g,'ein Brett'],[/Lerncheck-Zettel \(A5\) austeilen, Kriterien vorlesen, still arbeiten lassen\. Einsammeln und nach „sicher“ und „noch unsicher“ sortieren\./g,'Lerncheck-Zettel (A5) geben, Kriterien vorlesen, allein arbeiten lassen. Danach gemeinsam besprechen.'],[/Danach „([^“]+)“ (noch einmal )?spielen/g,'Danach „$1“ gegen die Lehrkraft $2spielen'],[/Stärkere zusätzlich 5, 6 und die Profi-Aufgabe\./g,'Danach 5, 6 und die Profi-Aufgabe.'],[/Pflicht für alle: /g,'Pflicht: '],[/Jedes Kind (sucht|entscheidet)/g,'Das Kind $1'],[/die Kinder ergänzen lassen/g,'das Kind ergänzen lassen'],[/ohne Partnerhilfe/g,'ohne Hilfe'],[/Kinder entscheiden jeweils und begründen ihre Entscheidung/g,'Das Kind entscheidet jeweils und begründet seine Entscheidung'],[/Kinder prüfen jeden Punkt und zeigen den Beleg/g,'Das Kind prüft jeden Punkt und zeigt den Beleg'],[/Kinder erklären, welches Merkmal/g,'Das Kind erklärt, welches Merkmal'],[/Kinder ergänzen den fehlenden Schritt und begründen ihn/g,'Das Kind ergänzt den fehlenden Schritt und begründet ihn'],[/Kinder zeigen, was/g,'Das Kind zeigt, was'],[/Kinder vermuten und zeigen/g,'Das Kind vermutet und zeigt'],[/Partner ausreden lassen; Rollen wechseln\./g,'Ausreden lassen; abwechselnd begründen.'],[/Der Partner prüft mit der Prüfliste\./g,'Du prüfst mit der Prüfliste.'],[/Zwei Teams zu zweit an einem Brett\./g,'Kind und Lehrkraft an einem Brett.'],[/Paare spielen sechs Züge und notieren beide\./g,'Kind und Lehrkraft spielen sechs Züge und notieren beide.'],[/Dann Zettel mit dem Nachbarpaar tauschen; dieses spielt die Partie nur nach Notation nach\./g,'Danach spielt das Kind die Partie nur nach der Notation nach.'],[/Paare finden und zeigen/g,'Das Kind findet und zeigt'],[/Kinder zeigen am Brett, an welcher Stelle sie nicht stimmt/g,'Das Kind zeigt am Brett, an welcher Stelle sie nicht stimmt'],[/,? ?(die )?Kinder zeigen sie\./g,', das Kind zeigt sie.'],[/ Vereinskinder merken \(für die Paarbildung\)\./g,''],[/Nach jedem Schritt kontrolliert der Partner\./g,'Nach jedem Schritt kontrollierst du.'],[/; der Partner kontrolliert\./g,'; du kontrollierst.'],[/ Vereinskinder bauen allein[^.]*\./g,''],[/ Ähnlich starke Paare; Vereinskinder spielen gegeneinander\./g,' Du spielst gegen das Kind.'],[/Allein aufbauen, Partner prüft;/g,'Allein aufbauen, du prüfst;'],[/Partnerspiel/g,'Spiel gegen die Lehrkraft'],[/Partnerarbeit/g,'Einzelarbeit'],[/Ein Brett pro Paar/g,'Ein Brett'],[/mit dem Daumen die eigene Sicherheit zeigen/g,'die eigene Sicherheit mit dem Daumen zeigen']];
function solo(plan){if(+plan.settings?.group!==1)return plan;const fix=t=>SOLO.reduce((x,[a,b])=>x.replace(a,b),String(t??''));for(const s of plan.sessions){for(const ph of s.phases)for(const k of ['teacher','learners','result','material','social','scan_teacher','scan_learners','scan_result','diff'])if(typeof ph[k]==='string')ph[k]=fix(ph[k]);s.mixed='Einzelförderung: Du spielst den Partner. Hilfen nur auf Nachfrage geben.';if(s.reserveFast)s.reserveFast=s.reserveFast.replace(/Mini-Spiel zu zweit \(3 Min\.\): ([^:]+):.*$/,'Mini-Spiel mit dir (3 Min.): $1. Du übernimmst die Rolle des Partners.').replace(/mit dem Nachbarpaar tauschen/,'mit dir besprechen');if(s.fitNote)s.fitNote=fix(s.fitNote).replace(/gemischte Paare nach Regel, /,'')}return plan}
// Von der Lehrkraft gewählte Methode sichtbar in den Übungsablauf übernehmen.
function methodize(plan){const id=plan.settings?.methodChosen;if(!id)return plan;const m=C.methods.find(x=>x.id===id);if(!m)return plan;for(const s of plan.sessions){const ph=s.phases.find(x=>x.method===id)||s.phases.find(x=>x.name==='Übung');if(!ph)continue;ph.method=id;const gameT=(String(ph.scan_teacher).match(/(Letzte|letzte) \d+ Minuten:.*$/)||[''])[0],gameL=(String(ph.scan_learners).match(/Danach „.*$/)||[''])[0];ph.scan_teacher='Methode „'+m.name+'“ mit den Aufgaben der Übung: '+m.instruction+(gameT?' '+gameT:'');ph.scan_learners='Nach „'+m.name+'“ arbeiten und jede Entscheidung am Brett begründen.'+(gameL?' '+gameL:'');ph.teacher='Methode „'+m.name+'“: '+m.instruction+' Aufgaben: die Übungsaufgaben des Arbeitsblatts. '+ph.teacher;s.methodNote='„'+m.name+'“, von dir gewählt. Passt sie nicht, im Plan bei der Übung „Anpassen“ wählen.'}return plan}
// Konkrete Nachfrage je Thema statt der abstrakten Frage nach dem Denkschritt.
const ASK={legal:'Steht dein König nach dem Zug sicher?',passed:'Steht auf deiner Linie oder daneben ein gegnerischer Bauer?',queenmate:'Hat der König nach deinem Zug noch ein Feld?',tworooks:"Welcher Turm ist Wächter, welcher Jäger?",counter:"Welche Figur ist bedroht? Was greifst du mit deinem Zug an?",skewer:"Was steht vorne, was steht dahinter?",clock:'Hast du die Figur schon berührt? Mit welcher Hand drückst du?',coordinates:'Zeig mir zuerst die Linie, dann die Reihe.',moves:'Wie darf diese Figur ziehen? Steht etwas im Weg?',pawn:'Ziehst du oder schlägst du? Gerade oder schräg?',defend:'Wer greift an? Wer schlägt zurück?',check:'Wer gibt Schach? Welche der drei Abwehren klappt hier?',mateIn1:'Ist es Schach? Kann der König weg, schlagen oder dazwischenziehen?',fairplay:'Welche Regel gilt hier? Wie klärt ihr das ruhig?',promotion:'Auf welcher Reihe wandelt der Bauer um? Welche Figur hilft am meisten?',hangingPiece:'Wer schlägt zurück, wenn du schlägst?',fork:'Welche zwei Figuren greifst du an? Steht deine Figur dort sicher?',pin:'Was steht hinter der angegriffenen Figur?',opening:'Welche Figur steht noch auf der Grundreihe?',endgame:'Passt der König noch ins Quadrat des Bauern?',castling:'Hat der König schon gezogen? Ist ein Feld besetzt oder angegriffen?',stalemate:'Steht der König im Schach? Hat Schwarz noch einen Zug?',notation:'Welche Figur ist es, und auf welches Feld zieht sie?',enpassant:'Hat der Bauer gerade einen Doppelschritt gemacht?',exchange:'Was gibst du, was bekommst du am Ende?',discoveredAttack:'Welche Linie wird frei, wenn die Figur wegzieht?',mateIn2:'Was kann Schwarz nach deinem ersten Zug tun?',calculation:'Welche zwei Züge vergleichst du? Was antwortet der Gegner?',planning:'Was ist dein Plan, und was macht der Gegner dagegen?',rookend:'Ist deine Grundreihe sicher?',doublecheck:'Welche Figuren geben Schach? Was hilft gegen beide?'};
function ask(plan){for(const s of plan.sessions){const t=s.topic||plan.settings.topic,q=ASK[t];if(!q)continue;const novice=window.Curriculum?.data?.[t]?.level==='Anfänger'||s.fit==='under';for(const ph of s.phases){for(const k of ['scan_teacher','teacher'])if(typeof ph[k]==='string'){ph[k]=ph[k].replace(/„Welcher Denkschritt fehlt\?“/g,'„'+q+'“');if(novice)ph[k]=ph[k].replace(/„Welcher Denkschritt fehlte\?“/g,'„Was hätte hier geholfen?“')}}}return plan}
// Früher fertig: kurzes Mini-Spiel je Thema (etwa 3 Minuten, zu zweit).
const FAST={legal:'Verbotene Felder: A stellt König und eine gegnerische Figur auf, B zeigt alle verbotenen Königsfelder.',passed:'Freibauer-Suche: A baut eine Bauernstellung, B zeigt alle Freibauern.',queenmate:'Damenmatt auf Zeit: A spielt mit Dame und König, B zählt die Züge, dann Rollen tauschen.',tworooks:"Treppen-Rennen: A und B bauen dieselbe Stellung auf. Wer setzt mit zwei Türmen in weniger Zügen matt? Dann Rollen tauschen.",counter:"Gegenangriff-Duell: A greift mit einem Bauern eine Figur von B an. B findet einen Fluchtzug mit Angriff oder Schach, dann Rollen tauschen.",skewer:"Spieß-Suche: A stellt König und Dame auf eine Linie, B findet mit Turm oder Läufer das Spießfeld, dann Rollen tauschen.",clock:'Uhren-Training: Fünf Züge mit Uhr, ein Kind achtet nur auf „ziehen, drücken, schreiben“.',coordinates:'Felder-Blitz: A nennt ein Feld, B tippt es an. Fünf richtige, dann Rollen tauschen.',moves:'Springer-Weg: Springer auf b1. Jeder sucht einen Weg nach h8 mit möglichst wenigen Zügen. Wer braucht weniger?',pawn:'Mini-Bauernkrieg: Je vier Bauern auf a bis d (Weiß auf Reihe 2, Schwarz auf Reihe 7). Wer zuerst die letzte Reihe erreicht, gewinnt.',defend:'Wache halten: A stellt eine weiße Figur und eine schwarze, die sie angreift. B deckt die weiße Figur mit einer weiteren Figur.',check:'Schach-Rätsel: A baut ein Schach mit König und einer Figur. B nennt alle Abwehrarten, die hier gehen.',mateIn1:'Mattbild bauen: Mit König und Dame gegen König ein Matt aufbauen. Der Partner prüft, ob es wirklich keine Abwehr gibt.',fairplay:'Regel-Quiz: A beschreibt eine Situation („Ich habe die Figur schon berührt …“), B nennt die Regel.',promotion:'Welche Figur?: A stellt einen Bauern auf die vorletzte Reihe und einen gegnerischen König in die Nähe. B wandelt um und begründet die Wahl.',hangingPiece:'Hängt was?: A baut eine Stellung mit fünf Figuren. B findet jede ungedeckte Figur.',fork:'Gabel-Suche: A stellt zwei schwarze Figuren auf. B findet ein Feld, von dem ein weißer Springer beide angreift. A achtet darauf, dass es so ein Feld gibt.',pin:'Fessel-Bild: A baut eine Fesselung mit Läufer, schwarzer Figur und König. B zeigt, welche Figur gefesselt ist und warum.',opening:'Entwicklungs-Wettlauf: Beide spielen sechs Züge aus der Grundstellung. Wer mehr Leichtfiguren entwickelt hat, ohne etwas zu verlieren, gewinnt.',endgame:'Quadrat-Duell: A stellt einen Bauern und einen gegnerischen König. B sagt mit der Quadratregel voraus, ob der König ihn einholt. Dann ausspielen.',castling:'Rochade erlaubt?: A baut eine Stellung mit König e1, Turm h1 und einer schwarzen Figur. B entscheidet mit der Prüfliste.',stalemate:'Patt-Falle: König und Dame gegen König. Vor jedem Damenzug prüfen: Hat Schwarz danach noch einen Zug?',notation:'Diktat-Partie: A diktiert vier Züge in Notation, B spielt sie am Brett nach.',enpassant:'En-passant-Falle: A baut eine Stellung, in der ein Bauer gerade einen Doppelschritt gemacht hat. B prüft, ob en passant möglich ist.',exchange:'Tauschrechnung: A baut einen Abtausch auf. B rechnet die Bilanz bis zum letzten Rückschlag.',discoveredAttack:'Versteckte Linie: A stellt Turm oder Läufer hinter eine eigene Figur. B findet einen Abzug, der etwas angreift.',mateIn2:'Verteidiger spielen: A zeigt einen Plan für Matt in zwei Zügen, B sucht als Verteidiger die beste Antwort.',calculation:'Kandidaten-Duell: Beide schreiben für dieselbe Stellung zwei Kandidatenzüge auf und vergleichen die Gegenantworten.',planning:'Plan ansagen: In einer Stellung aus der Übung sagt jeder seinen Plan in einem Satz, der andere nennt eine Gegenidee.',rookend:'Grundreihe prüfen: A baut eine Stellung mit Türmen und Bauern. B prüft, ob ein Grundreihenmatt droht.',doublecheck:'Doppelschach bauen: A baut ein Doppelschach. B zeigt, dass nur ein Königszug hilft.'};
function enrich(plan){for(const s of plan.sessions){const t=s.topic||plan.settings.topic,p=PROFI[t];if(FAST[t]&&!s.stunde0&&!/Mini-Spiel/.test(s.reserveFast||''))s.reserveFast='Expertenaufgabe, dann Mini-Spiel zu zweit (3 Min.): '+FAST[t];if(p&&!s.profi&&!s.stunde0)s.profi={task:p[0],answer:p[1]};if(!s.mixed)s.mixed=PAIR_SHORT}return plan}

